import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const source = await readFile(require.resolve('publicodes'), 'utf8');
if (/\brequire\(/.test(source)) throw new Error('Publicodes must be self-contained');
const bridge = await readFile(new URL('./publicodes-bridge.js', import.meta.url), 'utf8');
const license = await readFile(new URL('../assets/js/PUBLICODES-LICENSE.txt', import.meta.url), 'utf8');
const bundle = '// Generated by scripts/build-publicodes.mjs; Publicodes (MIT).\n/*\n' + license + '\n*/\n' +
  '(function () {\nconst module = { exports: {} };\n' +
  source.replace(/\/\/# sourceMappingURL=.*$/m, '') + '\n' + bridge + '\n})();\n';
// Normalize only presentation whitespace in the upstream source/comments.
const normalized = bundle.replace(/[ \t]+$/gm, '')
  .replace(/^[ \t]+/gm, indentation => indentation.replaceAll('\t', '  '));
await writeFile(new URL('../assets/js/publicodes_bundle.js', import.meta.url), normalized);
console.log('Generated shared Publicodes bundle');
